-- Thumbnails for the APOD gallery on owlastro.com/remote/<observatory>. image is the APOD's image on NASA's image
-- service (assets.science.nasa.gov/dynamicimage/…), which resizes on request: the site asks for ?w=360&h=240&fit=crop.
-- Paths under content/dam/ don't resize, so they're stored in their dynamicimage/assets/ form. The worker
-- (app/worker/apod.js) fills both columns for new APODs; the updates below fill them for the 38 from migration 0020.

alter table public.remote_apods add column image text, add column image_alt text;

update public.remote_apods set image = 'https://assets.science.nasa.gov/dynamicimage/assets/science/cds/apod/apod/2026/october/IC63.png', image_alt = 'The sky is speckled with stars. Bright tufts of emission nebulae trace across the image''s equator. Arcs and smudges of ionized oxygen emission also included.' where observatory = 'starfront' and apod_date = '2026-10-21';
