update public.remote_apods set image = 'https://assets.science.nasa.gov/dynamicimage/assets/science/cds/apod/apod/2026/june/hamster.jpg', image_alt = 'A gaseous structure that resembles a hamster wheel sits near the center of the image. Inside is a bright white dwarf star. There is a larger asymmetric gas bubble surrounding the inner nebula. A galaxy sits to the bottom right. The background is composed of foreground and background stars, as well a' where observatory = 'obstech-el-sauce' and apod_date = '2026-06-17';
